    return inventoryItems.filter(item => {
        const assetType = (item.assetType || "").trim().toLowerCase();
        const isMatchingAsset = assetType === requestedAsset;
        const isAvailable = item.status === "In Stock" ||
            item.status === "Yes";
        return isMatchingAsset && isAvailable;
    }).length;
